/**
 * Deterministic generator for the synthetic school fallback (#7).
 * Pure function of its inputs + seed, so `public/data/schools.json` can be regenerated byte-identically.
 */
import { SCHOOL_FORMS, type School, type SchoolForm } from '../../src/types/domain.ts';
import { featureContains, type KreisCollection, type Position } from './geo.ts';

export interface Gemeinde {
  ags: string;
  name: string;
  kreisId: string;
  population: number;
  areaKm2: number;
  lon: number;
  lat: number;
}

export const SCHOOL_COUNT = 300;
export const MIN_SCHOOLS_PER_KREIS = 2;
export const DEMO_JOIN_CODE = 'DEMO42';
/** Synthetic Schulnummern start with 9 so they never collide with real NRW Schulnummern (#33). */
export const DEMO_SCHOOL_ID = '900000';
/** The live-demo school: a Gesamtschule in Düsseldorf (seat of the Schulministerium). */
const DEMO_GEMEINDE_AGS = '05111000';
const DEMO_SCHOOL_NAME = 'Gesamtschule Düsseldorf-Mitte';

/**
 * Relative frequency of school forms. Deliberately not the real NRW mix (> 50 % Grundschulen):
 * the Mood-Check targets grades 5+, so secondary schools dominate the demo map.
 */
const FORM_WEIGHTS: Record<SchoolForm, number> = {
  grundschule: 10,
  hauptschule: 6,
  realschule: 15,
  sekundarschule: 5,
  gesamtschule: 18,
  gymnasium: 25,
  foerderschule: 7,
  berufskolleg: 14,
};

const STUDENT_COUNT_RANGE: Record<SchoolForm, [number, number]> = {
  grundschule: [120, 400],
  hauptschule: [180, 450],
  realschule: [400, 900],
  sekundarschule: [300, 700],
  gesamtschule: [700, 1500],
  gymnasium: [550, 1300],
  foerderschule: [70, 250],
  berufskolleg: [900, 3500],
};

const NAME_TEMPLATES: Record<SchoolForm, string[]> = {
  grundschule: ['Grundschule', 'Gemeinschaftsgrundschule'],
  hauptschule: ['Hauptschule', 'Städtische Hauptschule'],
  realschule: ['Realschule', 'Städtische Realschule'],
  sekundarschule: ['Sekundarschule'],
  gesamtschule: ['Gesamtschule', 'Städtische Gesamtschule'],
  gymnasium: ['Gymnasium', 'Städtisches Gymnasium'],
  foerderschule: ['Förderschule', 'Förderzentrum'],
  berufskolleg: ['Berufskolleg', 'Kaufmännisches Berufskolleg', 'Berufskolleg für Technik'],
};

/** Big cities get a district suffix ("Gesamtschule Köln-Nord"), which also keeps names unique. */
const DISTRICTS = ['Mitte', 'Nord', 'Süd', 'Ost', 'West', 'Nordost', 'Nordwest', 'Südost', 'Südwest'];
const BIG_CITY_POPULATION = 150_000;

/** No 0/O, 1/I/L – codes are typed from posters. */
const JOIN_CODE_ALPHABET = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
const JOIN_CODE_LENGTH = 6;

/** mulberry32 – tiny, fast, good enough for demo data. */
export { createRandom } from '../../src/lib/random.ts';
import { createRandom } from '../../src/lib/random.ts';

function pickWeighted<T>(random: () => number, items: readonly T[], weight: (item: T) => number): T {
  const total = items.reduce((sum, item) => sum + weight(item), 0);
  let r = random() * total;
  for (const item of items) {
    r -= weight(item);
    if (r < 0) return item;
  }
  return items[items.length - 1]!;
}

/** Every Kreis gets the minimum, the rest is split by population (largest remainder). */
export function allocateByPopulation(
  populationByKreis: Map<string, number>,
  count: number,
): Map<string, number> {
  const kreisIds = [...populationByKreis.keys()].sort();
  const totalPopulation = kreisIds.reduce((sum, id) => sum + populationByKreis.get(id)!, 0);
  const free = count - MIN_SCHOOLS_PER_KREIS * kreisIds.length;
  const quotas = kreisIds.map((id) => ({ id, quota: (free * populationByKreis.get(id)!) / totalPopulation }));
  const result = new Map(quotas.map(({ id, quota }) => [id, MIN_SCHOOLS_PER_KREIS + Math.floor(quota)]));
  const remaining = count - [...result.values()].reduce((a, b) => a + b, 0);
  [...quotas]
    .sort((a, b) => (b.quota % 1) - (a.quota % 1) || a.id.localeCompare(b.id))
    .slice(0, remaining)
    .forEach(({ id }) => result.set(id, result.get(id)! + 1));
  return result;
}

const round5 = (value: number) => Math.round(value * 1e5) / 1e5;

export function generateSchools(gemeinden: Gemeinde[], kreise: KreisCollection, seed = 20261021): School[] {
  const random = createRandom(seed);
  const int = (min: number, max: number) => min + Math.floor(random() * (max - min + 1));
  const kreisById = new Map(kreise.features.map((f) => [f.properties.id, f]));

  const gemeindenByKreis = new Map<string, Gemeinde[]>();
  for (const g of [...gemeinden].sort((a, b) => a.ags.localeCompare(b.ags))) {
    if (!kreisById.has(g.kreisId)) throw new Error(`Gemeinde ${g.ags} references unknown Kreis ${g.kreisId}`);
    gemeindenByKreis.set(g.kreisId, [...(gemeindenByKreis.get(g.kreisId) ?? []), g]);
  }
  const populationByKreis = new Map(
    [...gemeindenByKreis].map(([id, list]) => [id, list.reduce((sum, g) => sum + g.population, 0)]),
  );
  const countByKreis = allocateByPopulation(populationByKreis, SCHOOL_COUNT);

  const usedNames = new Set<string>([DEMO_SCHOOL_NAME]);
  const usedCodes = new Set<string>([DEMO_JOIN_CODE]);
  const districtCursor = new Map<string, number>();

  const joinCode = () => {
    let code: string;
    do {
      code = Array.from(
        { length: JOIN_CODE_LENGTH },
        () => JOIN_CODE_ALPHABET[int(0, JOIN_CODE_ALPHABET.length - 1)],
      ).join('');
    } while (usedCodes.has(code));
    usedCodes.add(code);
    return code;
  };

  const schoolName = (form: SchoolForm, g: Gemeinde) => {
    const templates = NAME_TEMPLATES[form];
    const base = templates[int(0, templates.length - 1)]!;
    const joiner = /^[\p{L}-]+$/u.test(g.name) ? '-' : ' ';
    const isBigCity = g.population >= BIG_CITY_POPULATION;
    // Big cities rotate through the districts so their schools spread over the suffixes.
    const cursor = districtCursor.get(g.ags) ?? 0;
    const districts = DISTRICTS.map((_, i) => DISTRICTS[(cursor + i) % DISTRICTS.length]);
    const candidates = [
      ...(isBigCity ? [] : [`${base} ${g.name}`]),
      ...districts.map((d) => `${base} ${g.name}${joiner}${d}`),
    ];
    let name = candidates.find((c) => !usedNames.has(c));
    for (let n = 2; !name; n++) {
      if (!usedNames.has(`${candidates[0]} ${n}`)) name = `${candidates[0]} ${n}`;
    }
    if (isBigCity) districtCursor.set(g.ags, cursor + 1);
    usedNames.add(name);
    return name;
  };

  /** Random point near the Gemeinde's inner point, but always inside its Kreis polygon. */
  const position = (g: Gemeinde): Position => {
    const kreis = kreisById.get(g.kreisId)!;
    const radiusKm = 0.35 * Math.sqrt(g.areaKm2);
    for (let attempt = 0; attempt < 30; attempt++) {
      const distance = radiusKm * Math.sqrt(random());
      const angle = random() * 2 * Math.PI;
      const lat = g.lat + (distance * Math.sin(angle)) / 111.32;
      const lon = g.lon + (distance * Math.cos(angle)) / (111.32 * Math.cos((g.lat * Math.PI) / 180));
      const point: Position = [round5(lon), round5(lat)];
      if (featureContains(kreis, point)) return point;
    }
    return [g.lon, g.lat];
  };

  const formIds = SCHOOL_FORMS.filter((f) => FORM_WEIGHTS[f] > 0);
  const schools: School[] = [];
  let nextId = Number(DEMO_SCHOOL_ID) + 1;

  for (const [kreisId, count] of [...countByKreis].sort(([a], [b]) => a.localeCompare(b))) {
    const list = gemeindenByKreis.get(kreisId)!;
    for (let i = 0; i < count; i++) {
      const isDemo = kreisId === DEMO_GEMEINDE_AGS.slice(0, 5) && i === 0;
      // Each Kreis starts with a Gymnasium or Gesamtschule – the core audience of the Mood-Check.
      const form: SchoolForm = isDemo
        ? 'gesamtschule'
        : i === 0
          ? random() < 0.5
            ? 'gymnasium'
            : 'gesamtschule'
          : pickWeighted(random, formIds, (f) => FORM_WEIGHTS[f]);
      // Berufskollegs sit in the larger towns of a Kreis.
      const gemeinde = isDemo
        ? list.find((g) => g.ags === DEMO_GEMEINDE_AGS)!
        : pickWeighted(random, list, (g) => (form === 'berufskolleg' ? g.population ** 2 : g.population));
      const [lon, lat] = position(gemeinde);
      const [minStudents, maxStudents] = STUDENT_COUNT_RANGE[form];
      schools.push({
        id: isDemo ? DEMO_SCHOOL_ID : String(nextId++),
        name: isDemo ? DEMO_SCHOOL_NAME : schoolName(form, gemeinde),
        schoolForm: form,
        kreisId,
        city: gemeinde.name,
        lat,
        lon,
        studentCount: isDemo ? 1100 : Math.round(int(minStudents, maxStudents) / 10) * 10,
        joinCode: isDemo ? DEMO_JOIN_CODE : joinCode(),
      });
    }
  }
  return schools.sort((a, b) => a.id.localeCompare(b.id));
}

/** One school per line: compact, but diffs stay readable. */
export function serializeSchools(schools: School[]): string {
  return `[\n${schools.map((s) => `  ${JSON.stringify(s)}`).join(',\n')}\n]\n`;
}
